function AuthScreen() {
  const [mode, setMode] = useState<"login" | "register">("register");
  const [message, setMessage] = useState("");
  const [login, loginState] = useLoginMutation();
  const [register, registerState] = useRegisterMutation();
  const busy = loginState.isLoading || registerState.isLoading;
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setMessage("");
    const form = new FormData(event.currentTarget);
    try {
      if (mode === "register") await register({ name: String(form.get("name")), email: String(form.get("email")), password: String(form.get("password")), organization: String(form.get("organization")) }).unwrap();
      else await login({ email: String(form.get("email")), password: String(form.get("password")) }).unwrap();
    } catch (error) { setMessage(errorMessage(error)); }
  }
  return <main className="auth-screen"><div className="auth-visual"><Link className="brand brand-light" href="/"><span className="brand-mark">✳</span><span>searchlight</span></Link><div className="auth-promise"><p className="eyebrow">SEO intelligence, with receipts</p><h1>Know what is real.<br /><span>Choose what to do next.</span></h1><p>One workspace for technical SEO, research, and the work your team ships.</p><div className="auth-proof"><span><i className="proof-dot" /> Provider data stays attributed</span><span><i className="proof-dot" /> First-party signals stay distinct</span></div></div><div className="auth-orbit orbit-a" /><div className="auth-orbit orbit-b" /><div className="auth-footer">Built for teams who need evidence behind the recommendation.</div></div><section className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><div className="auth-heading"><p className="eyebrow">Your workspace</p><h2>{mode === "register" ? "Create your account" : "Welcome back"}</h2><p>{mode === "register" ? "Start with a secure, private team workspace." : "Sign in to continue to your workspace."}</p></div>{mode === "register" && <><label>Full name<input name="name" autoComplete="name" required minLength={1} maxLength={100} placeholder="Alex Morgan" /></label><label>Organization<input name="organization" required minLength={2} maxLength={100} placeholder="Acme Studio" /></label></>}<label>Work email<input name="email" type="email" autoComplete="email" required placeholder="you@company.com" /></label><label>Password<input name="password" type="password" autoComplete={mode === "register" ? "new-password" : "current-password"} required minLength={mode === "register" ? 12 : 1} placeholder={mode === "register" ? "At least 12 characters" : "Your password"} /></label>{message && <p className="form-error" role="alert">{message}</p>}<button className="button button-primary auth-submit" disabled={busy}>{busy ? "One moment…" : mode === "register" ? "Create workspace" : "Sign in"}<span>→</span></button><p className="switch-auth">{mode === "register" ? "Already have an account?" : "New to Searchlight?"} <button type="button" onClick={() => { setMessage(""); setMode(mode === "register" ? "login" : "register"); }}>{mode === "register" ? "Sign in" : "Create an account"}</button></p><p className="auth-terms">Your workspace is isolated by organization. Connected data remains labeled by its source.</p></form></section></main>;
}

function errorMessage(error: unknown) {
  if (error && typeof error === "object" && "data" in error) {
    const data = (error as { data?: { error?: { message?: string } } }).data;
    return data?.error?.message ?? "The request could not be completed. Try again.";
  }
  return "The service could not be reached. Check that the API and database are running.";
}

